    def verifier(assign):
# Verify inputs and compute the numerator m of the reduced probability that Bob has a winning strategy.
# Game model: Toroidal grid rows x cols. State includes positions (wx, wy), (bx, by), last-axis used by each piece
# (0=H,1=V,2=None for initial), and player-to-move (0=Alice,1=Bob). Legal moves respect alternating axes.
# Bob wins if at some Bob-turn state he can move to exactly the white position in one step along the allowed axis.
# We compute the set of winning states for Bob via standard attractor/fixpoint iteration using reverse edges.
try:
    rows = int(assign.get('rows', None))
    cols = int(assign.get('cols', None))
except Exception:
    # Invalid assignment types
    return (False, None)
# Basic validation
if rows is None or cols is None:
    return (False, None)  # missing slots
if rows < 3 or cols < 3:
    return (False, None)  # grid too small to be nontrivial
# Build state space
W = rows
H = cols
# Encode axes: 0=H,1=V,2=None(initial)
AXES = [0,1]
def allowed_axes(last):
    if last == 2:
        return AXES
    return [1 - last]
