def move_pos(pos, axis, step):
    x, y = pos
    if axis == 0:  # horizontal
        return ((x + step) % W, y)
    else:  # vertical
        return (x, (y + step) % H)
# Generate all states
# State tuple: (wx, wy, bx, by, lw, lb, turn) with lw, lb in {0,1,2}, turn in {0,1}
states = {}
rev_states = []  # list of tuples by index
idx = 0
for wx in range(W):
    for wy in range(H):
        for bx in range(W):
            for by in range(H):
                for lw in (0,1,2):
                    for lb in (0,1,2):
                        for turn in (0,1):
                            states[(wx,wy,bx,by,lw,lb,turn)] = idx
                            rev_states.append((wx,wy,bx,by,lw,lb,turn))
                            idx += 1
N = idx
# Adjacency lists and reverse edges
edges = [[] for _ in range(N)]
rev_edges = [[] for _ in range(N)]
# Bob-immediate-capture flags
immediate_win = [False] * N
# Outdegree for Alice states (count of legal moves)
alice_outdeg = [0] * N
# Build transitions
for s_id in range(N):
    wx, wy, bx, by, lw, lb, turn = rev_states[s_id]
    if turn == 0:  # Alice's move (white moves)
        # White can move along allowed axes and both +/-1 steps
        for a in allowed_axes(lw):
            for step in (-1, 1):
                nwx, nwy = move_pos((wx, wy), a, step)
                nlw = a
                nstate = (nwx, nwy, bx, by, nlw, lb, 1)  # Bob's turn next
                nid = states[nstate]
                edges[s_id].append(nid)
                rev_edges[nid].append(s_id)
                alice_outdeg[s_id] += 1
    else:  # Bob's move (black moves)
        # Check if Bob can capture immediately
        can_cap = False
        for a in allowed_axes(lb):
            # A capture move must land exactly on white's position in one step along axis a
            # That means one of the two neighbors along axis equals (wx,wy)
            # Try both +/-1
            for step in (-1, 1):
                nbx, nby = move_pos((bx, by), a, step)
                if nbx == wx and nby == wy:
                    can_cap = True
                    break
            if can_cap:
                break
        if can_cap:
            immediate_win[s_id] = True
        # For non-capturing moves, add transitions to next states
        for a in allowed_axes(lb):
            for step in (-1, 1):
                nbx, nby = move_pos((bx, by), a, step)
                # If this move would capture, we do not add an edge (terminal)
                if nbx == wx and nby == wy:
                    continue
                nlb = a
                nstate = (wx, wy, nbx, nby, lw, nlb, 0)  # Alice's turn next
                nid = states[nstate]
                edges[s_id].append(nid)
                rev_edges[nid].append(s_id)
# Compute winning region W for Bob via attractor algorithm
winning = [False] * N
from collections import deque
q = deque()
# Initialize with immediate-win states
for s_id in range(N):
    if immediate_win[s_id]:
        winning[s_id] = True
        q.append(s_id)
# Track remaining non-winning successors for Alice states
# Initially, all successors are not marked winning, so rem = outdeg
rem = alice_outdeg[:]
while q:
    s = q.popleft()
    # Process predecessors
    for p in rev_edges[s]:
        if winning[p]:
            continue
        wx, wy, bx, by, lw, lb, turn = rev_states[p]
        if turn == 1:  # Bob's turn predecessor
            # Bob can move to a winning state, so this predecessor is winning
            winning[p] = True
            q.append(p)
        else:
            # Alice's turn predecessor: reduce remaining moves that avoid winning
            # Since successor s is winning for Bob, this move is bad for Alice
            rem[p] -= 1
            if rem[p] == 0:
                # All moves from p lead to Bob-winning states; hence p is winning for Bob
                winning[p] = True
                q.append(p)
# Count initial states (Alice to move, both last axes None) that are winning for Bob
total_pairs = W * H * (W * H - 1)
win_pairs = 0
# Iterate over ordered distinct placements
for wx in range(W):
    for wy in range(H):
        for bx in range(W):
            for by in range(H):
                if wx == bx and wy == by:
                    continue
                s0 = states[(wx, wy, bx, by, 2, 2, 0)]
                if winning[s0]:
                    win_pairs += 1
# Reduce fraction
import math
g = math.gcd(win_pairs, total_pairs)
m = win_pairs // g
# n = total_pairs // g  # not returned
# Sanity: ensure nontrivial and not all winning or none
if m == 0 or m == total_pairs // g:
    # Extremely degenerate parameters; reject
    return (False, None)
return (True, m)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

